function getEffectiveHP(){return Math.floor((ATTRS[0].hp+bonusHP)*(1+getPctBonus()/100))+getContainerHPBonus();}
function getEffectiveATK(){return((ATTRS[0].atk+bonusATK)*(1+getPctBonus()/100)).toFixed(2);}
