setInterval(function(){var now=Date.now(),keys=Object.keys(notifs);for(var i=0;i<keys.length;i++){var k=keys[i],n=notifs[k];if(!n)continue;if(!n.merging&&(now-n.tLast)>=MERGE_WAIT){n.merging=true;n.el.innerHTML='<span class="base">'+n.label+' '+(n.base+n.delta)+'</span>';}if(now-n.tCreate>=NOTIF_STAY){n.el.classList.add('fade-out');(function(nn,kk){setTimeout(function(){if(notifs[kk]===nn)delete notifs[kk];if(nn.el&&nn.el.parentNode)nn.el.remove();},300);})(n,k);}}},100);
