function renderAttrTab(el){var pct=getPctBonus(),hpFlat=getContainerHPBonus(),ls=getLifestealPct();var h='<div class="attr-title">\u4eba\u7269\u5c5e\u6027</div>';h+='<div class="attr-row" data-attr="hp"><span class="attr-label">\u8840\u91cf</span><span class="attr-val">'+fmtHP(playerHP)+'/'+fmtHP(playerMaxHP)+' ('+pct+'%'+(hpFlat>0?'+'+hpFlat:'')+')</span></div>';h+='<div class="attr-row" data-attr="atk"><span class="attr-label">\u653b\u51fb</span><span class="attr-val">'+getEffectiveATK()+' ('+pct+'%</span></div>';h+='<div class="attr-row" data-attr="def"><span class="attr-label">\u9632\u5fa1</span><span class="attr-val">'+getEffectiveDEF()+' ('+pct+'%</span></div>';h+='<div class="attr-row" data-attr="rec"><span class="attr-label">\u81ea\u7136\u6062\u590d</span><span class="attr-val">'+getEffectiveREC()+'</span></div>';h+='<div class="attr-row" data-attr="ls"><span class="attr-label">\u5438\u8840</span><span class="attr-val">'+(ls*100).toFixed(2)+'%</span></div>';el.innerHTML=h;el.querySelectorAll('.attr-row').forEach(function(row){row.addEventListener('click',function(){showAttrDetail(row.getAttribute('data-attr'));});});}
function renderStatsTab(el){var h='<div class="attr-title">\u51fb\u6740\u7edf\u8ba1</div>',any=false;Object.keys(MONSTERS).forEach(function(k){var c=monsterKills[k]||0;if(c>0){h+='<div class="attr-row"><span class="attr-label">'+MONSTERS[k].name+'</span><span class="attr-val">'+c+'\u53ea</span></div>';any=true;}});if(!any)h+='<div style="color:#ccc;font-size:13px;padding:20px 0;text-align:center">\u6682\u65e0\u51fb\u6740\u8bb0\u5f55</div>';el.innerHTML=h;}
function renderCodexTab(el){var list=[{id:'mosquitoContainer',source:'\u5c0f\u96c4\u868a\u6389\u843d',effect:'\u51fb\u6740\u5c0f\u96c4\u868a\u65f6\uff0c\u8840\u91cf\u4e0a\u9650+1',max:100,getV:function(){return containerOwned?Math.min(monsterKills.mosquito-containerKillBase,100):0;}},{id:'mosquitoFemaleContainer',source:'\u5c0f\u96cc\u868a\u6389\u843d',effect:'\u51fb\u6740\u5c0f\u96cc\u868a\u65f6\uff0c\u5438\u8840\u5c5e\u6027+0.01%',max:100,getV:function(){return containerFemaleOwned?Math.min(monsterKills.mosquitoFemale-containerFemaleKillBase,100):0;}}];var h='<div class="attr-title">\u56fe\u9274</div><div class="grid">';for(var i=0;i<list.length;i++){var s=list[i],it=ITEMS[s.id],owned=(s.id==='mosquitoContainer')?containerOwned:containerFemaleOwned,complete=owned&&(s.getV()>=s.max),bc=complete?' codex-black':(owned?' codex-gold':'');if(enchanted[s.id])bc+=' codex-enchanted';h+='<div class="slot has-item'+bc+'" data-ci="'+i+'">'+it.name+'</div>';}h+='</div>';el.innerHTML=h;el.querySelectorAll('.slot').forEach(function(slot){slot.addEventListener('click',function(){var idx=parseInt(slot.getAttribute('data-ci')),s=list[idx],it=ITEMS[s.id],owned=(s.id==='mosquitoContainer')?containerOwned:containerFemaleOwned,mh='<div class="modal-name">'+it.name+'</div><div class="modal-meta">\u6765\u6e90\uff1a'+s.source+'</div><div class="modal-meta">\u6548\u679c\uff1a'+s.effect+'</div>';if(owned)mh+='<div class="modal-desc">'+it.desc+'</div><div class="modal-meta">\u8fdb\u5ea6\uff1a'+s.getV()+'/'+s.max+'</div>';mh+='<div class="modal-btns"><button class="btn btn-sm" id="mbClose">\u5173\u95ed</button></div>';$modalBox.innerHTML=mh;$modalOverlay.classList.add('show');document.getElementById('mbClose').addEventListener('click',closeModal);});});}
