function startCultivate(){if(playerState==='traveling'||playerState==='cultivating')return;playerState='cultivating';expTimer=setInterval(function(){setExp(exp+applyCultivateBonus(10+getCultivateGainBonus()));},10000);regenTimer=setInterval(function(){if(playerHP<playerMaxHP)playerHP=Math.min(playerMaxHP,playerHP+playerMaxHP*0.01);renderMain();},1000);renderMain();}
function stopCultivate(){if(playerState!=='cultivating')return;playerState='idle';clearInterval(expTimer);expTimer=null;if(regenTimer){clearInterval(regenTimer);regenTimer=null;}renderMain();}
$btnCult.addEventListener('click',function(){if(playerState==='traveling'){showFloatTip($btnCult,'\u6e38\u5386\u4e2d\u65e0\u6cd5\u8fdb\u884c\u4fee\u70bc');return;}playerState==='cultivating'?stopCultivate():startCultivate();});
$btnBreak.addEventListener('click',function(){var req=reqFor(stageIdx);if(exp<req)return;var isRealm=isRealmBreakthrough(stageIdx);if(isRealm&&stageIdx>=17){showModal({name:'\u63d0\u793a',desc:'\u5f53\u524d\u5883\u754c\u7a81\u7834\u6682\u672a\u5f00\u653e',special:true});return;}var need=isRealm?REALM_BREAK_ITEMS[0]:null;if(need){var have=countItem(backpack,need.id);if(have<need.count){showModal({name:'\u63d0\u793a',desc:'\u9700\u8981'+need.count+'\u4e2a'+ITEMS[need.id].name+'\uff0c\u5f53\u524d\u62e5\u6709'+have+'\u4e2a',special:true});return;}}var h='<div class="modal-name">'+(isRealm?'\u5883\u754c\u7a81\u7834':'\u9636\u6bb5\u7a81\u7834')+'</div>';h+='<div class="modal-desc">\u7a81\u7834\u6240\u9700\u4fee\u4e3a\uff1a'+req+'\u3000\u5f53\u524d\u4fee\u4e3a\uff1a'+exp+'</div>';if(need)h+='<div class="modal-desc">\u6240\u9700\u7269\u54c1\uff1a'+ITEMS[need.id].name+' \u00d7'+need.count+'\u3000\u62e5\u6709\uff1a'+countItem(backpack,need.id)+'</div>';h+='<div class="modal-desc" style="color:#999">\u7a81\u7834\u540e\u5883\u754c\uff1a'+getFullName(stageIdx+1)+'</div>';h+='<div class="modal-btns"><button class="btn btn-sm" id="mbBreakOk">\u786e\u5b9a</button><button class="btn btn-sm" id="mbBreakNo">\u53d6\u6d88</button></div>';$modalBox.innerHTML=h;$modalOverlay.classList.add('show');document.getElementById('mbBreakNo').addEventListener('click',closeModal);document.getElementById('mbBreakOk').addEventListener('click',function(){closeModal();var req2=reqFor(stageIdx);if(exp<2)return;if(isRealm){var need2=REALM_BREAK_ITEMS[0];if(countItem(backpack,need2.id)<need2.count)return;removeItems(backpack,need2.id,need2.count);}setExp(exp-req2);stageIdx+=1;refreshMaxHP();renderMain();saveGame();});});
var infoInterval=null;var $tabs=document.querySelectorAll('.tab-btn'),$pages=document.querySelectorAll('.page');
