function findSlot(arr,id){for(var i=0;i<arr.length;i++){if(arr[i].id===id)return i;}return-1;}
function addItem(arr,id,maxSlots,qty){qty=qty||1;var idx=findSlot(arr,id);if(idx>=0){var def=ITEMS[id];if(arr[idx].count+qty<=def.maxStack){arr[idx].count+=qty;return true;}}if(arr.length<maxSlots){arr.push({id:id,count:qty});return true;}return false;}
function removeOne(arr,id){var idx=findSlot(arr,id);if(idx<0)return false;arr[idx].count-=1;if(arr[idx].count<=0)arr.splice(idx,1);return true;}
function removeItems(arr,id,count){var idx=findSlot(arr,id);if(idx<0)return false;if(arr[idx].count<count)return false;arr[idx].count-=count;if(arr[idx].count<=0)arr.splice(idx,1);return true;}
function moveItem(from,to,fromIdx,maxTo){if(fromIdx>=from.length)return false;var item=from[fromIdx];if(ITEMS[item.id].special)return false;var ti=findSlot(to,item.id);if(ti>=0){to[ti].count+=item.count;from.splice(fromIdx,1);return true;}if(to.length<maxTo){to.push({id:item.id,count:item.count});from.splice(fromIdx,1);return true;}return false;}
function getEquipEffectDesc(id){if(ITEMS[id]&&ITEMS[id].effectDesc)return ITEMS[id].effectDesc;var rk=null;var keys=Object.keys(RECIPES);for(var i=0;i<keys.length;i++){if(RECIPES[keys[i]].resultId===id){rk=keys[i];break;}}if(!rk)return "";var r=RECIPES[rk],eff=[];if(r.effects.cultivateBonus)eff.push("修为获取+"+Math.round(r.effects.cultivateBonus*100)+"%");if(r.effects.hpMax)eff.push("血量上限+"+r.effects.hpMax);if(r.effects.atk)eff.push("攻击+"+r.effects.atk);if(r.effects.def)eff.push("防御+"+r.effects.def);if(r.effects.rec)eff.push("自然恢复+"+r.effects.rec);if(r.effects.lifestealBonus)eff.push("吸血+"+(r.effects.lifestealBonus*100).toFixed(2)+"%");return eff.join("，");}
function showModal(opts){var html='<div class="modal-name">'+opts.name+'</div><div class="modal-desc">'+opts.desc+'</div><div class="modal-meta">\u54c1\u8d28\uff1a'+opts.quality+'</div>';if(opts.equippable){var _eff=opts.effect||'';if(!_eff){var _iks=Object.keys(ITEMS);for(var _ii=0;_ii<_iks.length;_ii++){if(ITEMS[_iks[_ii]].name===opts.name&&ITEMS[_iks[_ii]].effectDesc){_eff=ITEMS[_iks[_ii]].effectDesc;break;}}}html+='<div class="modal-meta">\u88c5\u5907\u6548\u679c\uff1a'+(_eff||'\u65e0')+'</div>';}if(!opts.equippable)html+='<div class="modal-meta">\u5927\u5c0f\uff1a'+opts.size+'　\u53ef\u5806\u53e0\uff1a'+opts.maxStack+'</div>';if(!opts.special&&opts.price!==undefined&&opts.price!==null)html+='<div class="modal-meta">\u51fa\u552e\u4ef7\u683c\uff1a'+opts.price+' \u94dc\u94b1</div>';html+='<div class="modal-btns">';if(opts.btn1)html+='<button class="btn btn-sm" id="mb1">'+opts.btn1+'</button>';if(opts.btn2)html+='<button class="btn btn-sm" id="mb2">'+opts.btn2+'</button>';if(opts.btn3)html+='<button class="btn btn-sm" id="mb3">'+opts.btn3+'</button>';html+='<button class="btn btn-sm" id="mbClose">\u5173\u95ed</button></div>';$modalBox.innerHTML=html;$modalOverlay.classList.add('show');document.getElementById('mbClose').addEventListener('click',closeModal);if(opts.btn1&&opts.on1)document.getElementById('mb1').addEventListener('click',function(){closeModal();opts.on1();});if(opts.btn2&&opts.on2)document.getElementById('mb2').addEventListener('click',function(){closeModal();opts.on2();});if(opts.btn3&&opts.on3)document.getElementById('mb3').addEventListener('click',function(){closeModal();opts.on3();});}
