html+='</div><div class="grid" style="grid-template-columns:repeat(1,1fr);width:48px">';
for(var i=3;i<6;i++){if(i<eqSlots&&equipment[i]){var it=ITEMS[equipment[i]];html+='<div class="slot has-item" data-eidx="'+i+'" style="background:#e8e0d0">'+it.name.substring(0,2)+'</div>';}else if(i<eqSlots){html+='<div class="slot" data-eidx="'+i+'" style="border-style:dashed"></div>';}else{html+='<div class="slot locked"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#aaa" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="11" width="18" height="11" rx="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/></svg></div>';}}
html+='</div></div>';
