for(var i=0;i<BACKPACK_SLOTS;i++){if(i<backpack.length){var it=ITEMS[backpack[i].id];html+='<div class="slot has-item" data-idx="'+i+'" data-loc="backpack">'+it.name+'<span class="count">x'+backpack[i].count+'</span></div>';}else html+='<div class="slot"></div>';}
html+='</div>';$storageWrap.innerHTML=html;
